        args_info <- formals(ctcisQTL)
        cat("Function parameters:", names(args_info), "\n")
    }, error = function(e) {
        cat("Could not retrieve function parameters\n")
    })
}

# Run ctcisQTL analysis without the 'cis' parameter first
cat("Attempting ctcisQTL analysis without cis parameter...\n")
results <- NULL

tryCatch({
    # Method 1: Try without cis parameter
    results <- ctcisQTL(X=X, Y=Y, W=W, C=C, Xpos=Xpos, Ypos=Ypos)
    cat("Analysis successful without cis parameter!\n")
}, error = function(e1) {
    cat("Method 1 failed:", conditionMessage(e1), "\n")

    # Method 2: Try with different parameter names
    tryCatch({
        results <<- ctcisQTL(X=X, Y=Y, W=W, C=C, Xpos=Xpos, Ypos=Ypos, window=1000000)
        cat("Analysis successful with 'window' parameter!\n")
    }, error = function(e2) {
        cat("Method 2 failed:", conditionMessage(e2), "\n")

        # Method 3: Try with cis_window
        tryCatch({
            results <<- ctcisQTL(X=X, Y=Y, W=W, C=C, Xpos=Xpos, Ypos=Ypos, cis_window=1000000)
            cat("Analysis successful with 'cis_window' parameter!\n")
        }, error = function(e3) {
            cat("Method 3 failed:", conditionMessage(e3), "\n")

            # Method 4: Try with dist parameter
            tryCatch({
                results <<- ctcisQTL(X=X, Y=Y, W=W, C=C, Xpos=Xpos, Ypos=Ypos, dist=1000000)
                cat("Analysis successful with 'dist' parameter!\n")
            }, error = function(e4) {
                cat("All methods failed. Final attempt with minimal parameters:\n")

                # Method 5: Minimal parameters
                tryCatch({
                    results <<- ctcisQTL(X, Y, W, C, Xpos, Ypos)
                    cat("Analysis successful with minimal parameters!\n")
                }, error = function(e5) {
                    cat("All methods failed:\n")
                    cat("Error 1:", conditionMessage(e1), "\n")
                    cat("Error 2:", conditionMessage(e2), "\n")
                    cat("Error 3:", conditionMessage(e3), "\n")
                    cat("Error 4:", conditionMessage(e4), "\n")
                    cat("Error 5:", conditionMessage(e5), "\n")
                })
            })
        })
    })
})

# Check if analysis was successful and save results
if (!is.null(results)) {
    cat("ctcisQTL analysis completed successfully!\n")
    cat("Results class:", class(results), "\n")

    if (is.data.frame(results) || is.matrix(results)) {
        cat("Results dimensions:", nrow(results), "x", ncol(results), "\n")
        cat("Column names:", paste(colnames(results), collapse=", "), "\n")

        # Display first few rows
        if (nrow(results) > 0) {
            cat("First few rows:\n")
            print(head(results, min(3, nrow(results))))
        }
    }

    # Save results
    output_file <- "/mnt/data/lengyang/youjia_project/autoba/BABench/src/promptbio-bench/tasks/a-15-2/result_10/toolsgenie_20260516/mQTL_results.tsv"

    tryCatch({
        write.table(results, file=output_file, sep="\t", row.names=FALSE, quote=FALSE)
        cat("Results saved successfully to:", output_file, "\n")

        # Verify file creation
        if (file.exists(output_file)) {
            cat("File verification: SUCCESS\n")
            cat("File size:", file.size(output_file), "bytes\n")
        }
    }, error = function(e) {
        cat("Error saving results:", conditionMessage(e), "\n")

        # Try alternative save method
        tryCatch({
            write.csv(results, file=gsub(".tsv", ".csv", output_file), row.names=FALSE)
            cat("Results saved as CSV instead\n")
        }, error = function(e2) {
            cat("CSV save also failed:", conditionMessage(e2), "\n")
        })
    })

} else {
    cat("ERROR: ctcisQTL analysis failed - results object is NULL\n")

    # Provide help information
    cat("\nTrying to get help for ctcisQTL function:\n")
    tryCatch({
        help(ctcisQTL)
    }, error = function(e) {
        cat("Help not available for ctcisQTL\n")
    })
}

cat("Analysis complete.\n")

